import{_ as e,c as t,o as r,V as a}from"./chunks/framework.B6I5AJO8.js";const k=JSON.parse('{"title":"nb02 · Markdown chunking","description":"","frontmatter":{},"headers":[],"relativePath":"research/markdown-chunking.md","filePath":"research/markdown-chunking.md"}'),n={name:"research/markdown-chunking.md"},o=a('<h1 id="nb02-·-markdown-chunking" tabindex="-1">nb02 · Markdown chunking <a class="header-anchor" href="#nb02-·-markdown-chunking" aria-label="Permalink to &quot;nb02 · Markdown chunking&quot;">​</a></h1><p><strong>Notebook:</strong> <code>notebooks/nb02_markdown_chunking_strategies.ipynb</code> · <strong>Status:</strong> done</p><h2 id="the-question" tabindex="-1">The question <a class="header-anchor" href="#the-question" aria-label="Permalink to &quot;The question&quot;">​</a></h2><p>How should Markdown (the bulk of the KDK / Kano docs) be split into chunks so that retrieval is accurate <strong>and</strong> code blocks are never cut in half?</p><h2 id="strategies-compared" tabindex="-1">Strategies compared <a class="header-anchor" href="#strategies-compared" aria-label="Permalink to &quot;Strategies compared&quot;">​</a></h2><p>Several strategies were benchmarked against a recursive-character-text-split (RCT) baseline, including AST-aware variants that merge small sections and prepend a heading <strong>breadcrumb</strong> to each chunk for context.</p><table><thead><tr><th>Strategy</th><th>Idea</th><th>Result</th></tr></thead><tbody><tr><td>RCT (baseline)</td><td>Fixed-size recursive character split</td><td>reference point</td></tr><tr><td>AST-merge + breadcrumb (winner)</td><td>Split on Markdown AST, merge small nodes, prefix heading breadcrumb</td><td>see below</td></tr></tbody></table><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><p><strong>Winner: AST-merge + breadcrumb, <code>chunk_size = 500</code>.</strong></p><ul><li><strong>100% code-block integrity</strong> — no code block split across chunks.</li><li><strong>~2× the bundle efficiency</strong> of the RCT baseline (more relevant context per token).</li></ul><p>Measured with the shared deterministic retrieval metrics (<code>recall@k</code>, source coverage) over a gold query set.</p><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to &quot;Reproduce&quot;">​</a></h2><p>The benchmark is scriptable (gold set → deterministic metrics → parameter sweep on the winner). See the <code>chunking_lab/</code> helpers next to the notebook for the exact entry points.</p><h2 id="in-production" tabindex="-1">In production <a class="header-anchor" href="#in-production" aria-label="Permalink to &quot;In production&quot;">​</a></h2><p>This strategy is the Markdown chunker in the <a href="/knowledge/architecture/ingestion-pipeline.html">ingestion pipeline</a>.</p>',15),i=[o];function s(c,d,h,l,u,p){return r(),t("div",null,i)}const b=e(n,[["render",s]]);export{k as __pageData,b as default};
